 static T Find<T>(DependencyObject root,Func<T,bool> match)where T:DependencyObject{var o=root as T;if(o!=null&&match(o))return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=Find<T>(VisualTreeHelper.GetChild(root,i),match);if(child!=null)return child;}return null;}
 static void Tab(Window w,string text){var b=Find<Button>(w,x=>Convert.ToString(x.Content)==text);b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));w.UpdateLayout();}
