 Tab(w,"显示与详情");Toggle(w,"在任务栏显示实时监控");Check("taskbar can be hidden without quitting pet",!IsWindowVisible(taskbar.Handle)&&pet.IsVisible);Check("click card settings persist",assistant.Config.Monitor.ClickCard);
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"monitor-ui-results.json"),"{\"checks\":"+checks+",\"failures\":"+failures+"}");Console.WriteLine("Checks: "+checks+" Failures: "+failures);return failures==0?0:1;}
